#!/usr/bin/env node
// scaffold-rich-text-editor.js — v78 ship a Tiptap-based RichTextEditor
// component so the LLM doesn't reinvent contenteditable from scratch.
// Adds @tiptap/react + @tiptap/starter-kit + @tiptap/pm to deps.
//
// Idempotent. Marker: '// Generated by scaffold-rich-text-editor'.
'use strict';

var fs = require('fs');
var path = require('path');

function parseArgs(argv) {
  var out = {};
  for (var i = 2; i < argv.length; i++) {
    var a = argv[i];
    if (a === '--target') out.target = argv[++i];
    else if (a === '--force') out.force = true;
    else if (a === '--dry-run') out.dryRun = true;
  }
  if (!out.target) { console.error('Usage: scaffold-rich-text-editor --target FRONTEND_DIR'); process.exit(1); }
  return out;
}

function marker() { return '// Generated by scaffold-rich-text-editor — DO NOT EDIT BY HAND. Re-run to refresh.'; }

function writeIfManaged(file, content, force, dryRun) {
  if (fs.existsSync(file)) {
    var existing = fs.readFileSync(file, 'utf-8');
    if (!/Generated by scaffold-rich-text-editor/.test(existing) && !force) return { written: false, reason: 'exists-handauthored' };
    if (existing === content) return { written: false, reason: 'unchanged' };
  }
  if (dryRun) return { written: false, reason: 'dry-run' };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  return { written: true };
}

function ensureDep(pkgPath, deps, dryRun) {
  if (!fs.existsSync(pkgPath)) return { changed: false, reason: 'no-package-json' };
  var pkg; try { pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8')); } catch (_) { return { changed: false, reason: 'parse-error' }; }
  pkg.dependencies = pkg.dependencies || {};
  var added = [];
  Object.keys(deps).forEach(function (k) {
    if (!pkg.dependencies[k] && !(pkg.devDependencies || {})[k]) { pkg.dependencies[k] = deps[k]; added.push(k); }
  });
  if (!added.length) return { changed: false, reason: 'already-present' };
  if (dryRun) return { changed: false, reason: 'dry-run', added: added };
  fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
  return { changed: true, added: added };
}

var RTE = [
  marker(),
  "import { useEditor, EditorContent } from '@tiptap/react';",
  "import StarterKit from '@tiptap/starter-kit';",
  "import { Button } from '~/components/ui/button';",
  "import { Bold, Italic, List, ListOrdered, Quote, Strikethrough, Redo, Undo } from 'lucide-react';",
  "import { cn } from '~/lib/utils';",
  '',
  'export interface RichTextEditorProps {',
  '  value?: string;',
  '  onChange?: (html: string) => void;',
  '  placeholder?: string;',
  '  className?: string;',
  '  testId?: string;',
  '}',
  '',
  "export function RichTextEditor({ value = '', onChange, placeholder = 'Write something…', className, testId = 'rich-text-editor' }: RichTextEditorProps) {",
  '  const editor = useEditor({',
  '    extensions: [StarterKit],',
  '    content: value,',
  "    editorProps: { attributes: { class: 'prose prose-sm max-w-none focus:outline-none min-h-[120px] p-3', placeholder } },",
  '    onUpdate: ({ editor }) => { onChange?.(editor.getHTML()); },',
  '  });',
  '',
  '  if (!editor) return null;',
  '',
  '  return (',
  "    <div className={cn('rounded-md border', className)} data-testid={testId}>",
  "      <div className=\"flex flex-wrap items-center gap-1 border-b p-2\">",
  '        <Button type="button" size="sm" variant="ghost" onClick={() => editor.chain().focus().toggleBold().run()} data-testid={`${testId}-bold`}><Bold className="h-4 w-4" /></Button>',
  '        <Button type="button" size="sm" variant="ghost" onClick={() => editor.chain().focus().toggleItalic().run()} data-testid={`${testId}-italic`}><Italic className="h-4 w-4" /></Button>',
  '        <Button type="button" size="sm" variant="ghost" onClick={() => editor.chain().focus().toggleStrike().run()} data-testid={`${testId}-strike`}><Strikethrough className="h-4 w-4" /></Button>',
  '        <Button type="button" size="sm" variant="ghost" onClick={() => editor.chain().focus().toggleBlockquote().run()} data-testid={`${testId}-quote`}><Quote className="h-4 w-4" /></Button>',
  '        <Button type="button" size="sm" variant="ghost" onClick={() => editor.chain().focus().toggleBulletList().run()} data-testid={`${testId}-ul`}><List className="h-4 w-4" /></Button>',
  '        <Button type="button" size="sm" variant="ghost" onClick={() => editor.chain().focus().toggleOrderedList().run()} data-testid={`${testId}-ol`}><ListOrdered className="h-4 w-4" /></Button>',
  '        <div className="mx-1 h-5 w-px bg-border" />',
  '        <Button type="button" size="sm" variant="ghost" onClick={() => editor.chain().focus().undo().run()} data-testid={`${testId}-undo`}><Undo className="h-4 w-4" /></Button>',
  '        <Button type="button" size="sm" variant="ghost" onClick={() => editor.chain().focus().redo().run()} data-testid={`${testId}-redo`}><Redo className="h-4 w-4" /></Button>',
  '      </div>',
  '      <EditorContent editor={editor} />',
  '    </div>',
  '  );',
  '}',
  '',
].join('\n');

function main() {
  var args = parseArgs(process.argv);
  var r = writeIfManaged(path.join(args.target, 'app/components/ui/rich-text-editor.tsx'), RTE, args.force, args.dryRun);
  var d = ensureDep(path.join(args.target, 'package.json'), {
    '@tiptap/react': '^2.5.0',
    '@tiptap/starter-kit': '^2.5.0',
    '@tiptap/pm': '^2.5.0',
  }, args.dryRun);
  console.log('scaffold-rich-text-editor: rich-text-editor.tsx=' + (r.written ? 'wrote' : r.reason) + ' deps=' + (d.changed ? '+' + d.added.join(',') : d.reason));
}

main();
